  });
  const boxGeo = new THREE.BoxGeometry(1, 1, 1);
  const rand = mulberry32(1337);
  for (let i = 0; i < 26; i++) {
    const w = 0.7 + rand() * 1.5;
    const h = 1.4 + rand() * 5.4;
    const d = 0.6 + rand() * 1.4;
