function makeLensShape() {
  const s = new THREE.Shape();
  s.moveTo(-0.052, 0.014);
  s.bezierCurveTo(-0.048, 0.05, -0.002, 0.064, 0.036, 0.048);
  s.bezierCurveTo(0.066, 0.034, 0.072, -0.008, 0.042, -0.036);
  s.bezierCurveTo(0.016, -0.06, -0.026, -0.052, -0.044, -0.024);
  s.bezierCurveTo(-0.052, -0.01, -0.054, 0.002, -0.052, 0.014);
  return s;
}

