import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const browser = await chromium.launch({
  headless: false,
  args: [
    '--use-fake-ui-for-media-stream',
    '--use-fake-device-for-media-stream',
    '--enable-unsafe-swiftshader',
    '--enable-gpu',
    '--ignore-gpu-blocklist',
    '--enable-unsafe-webgpu',
    '--use-angle=vulkan',
    '--enable-features=Vulkan',
    '--use-vulkan=swiftshader',
    '--use-webgpu-adapter=swiftshader',
    '--disable-vulkan-surface',
  ],
});

const context = await browser.newContext({ viewport: { width: 1280, height: 900 } });
await context.grantPermissions(['camera'], { origin: 'http://localhost:3000' });
const page = await context.newPage();

const errors = [];
page.on('console', (msg) => {
  if (msg.type() === 'error') errors.push(`console: ${msg.text()}`);
});
page.on('pageerror', (error) => errors.push(`pageerror: ${error.message}`));

await page.goto('http://localhost:3000/', { waitUntil: 'load', timeout: 45000 });
await page.waitForFunction(() => window.__spidermotion, null, { timeout: 20000 });
await page.waitForTimeout(1500);
await page.evaluate(() => window.__spidermotion.hideStart?.());
// Force the live path even under automation.
await page.evaluate(() => window.__spidermotion.connect());

for (let i = 0; i < 60; i++) {
  await page.waitForTimeout(1000);
  const snapshot = await page.evaluate(() => ({
    ...window.__spidermotion.snapshot(),
    tracker: window.__spidermotion.state.tracker
      ? {
          pose: Boolean(window.__spidermotion.state.tracker.pose),
          face: Boolean(window.__spidermotion.state.tracker.face),
          delegate: window.__spidermotion.state.tracker.delegate,
          faceDelegate: window.__spidermotion.state.tracker.faceDelegate,
          running: window.__spidermotion.state.tracker.running,
          faceEnabled: window.__spidermotion.state.tracker.faceEnabled,
        }
      : null,
    video: {
      w: document.getElementById('video').videoWidth,
      h: document.getElementById('video').videoHeight,
      ready: document.getElementById('video').readyState,
    },
    status: document.getElementById('statusText').textContent,
    hint: document.getElementById('hintText').textContent,
    landmark: document.getElementById('landmarkInfo').textContent,
    latency: document.getElementById('latency').textContent,
  }));
  console.log(i, JSON.stringify(snapshot));
  if (snapshot.mode === 'live' || (snapshot.tracker && !snapshot.tracker.running)) break;
}

await page.screenshot({ path: 'screenshots/live-fakecam.png' });
console.log('ERRORS', JSON.stringify(errors, null, 2));
await browser.close();

