import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const browser = await chromium.launch({
  headless: false,
  args: [
    '--use-fake-ui-for-media-stream',
    '--use-fake-device-for-media-stream',
    '--enable-unsafe-swiftshader',
    '--ignore-gpu-blocklist',
  ],
});

const results = {};

async function capture(name, viewport, fn) {
  const context = await browser.newContext({ viewport });
  await context.grantPermissions(['camera'], { origin: 'http://localhost:3000' });
  await context.addInitScript(() => {
    Object.defineProperty(navigator, 'webdriver', { get: () => false });
  });
  const page = await context.newPage();
  const errors = [];
  page.on('console', (msg) => {
    if (msg.type() === 'error') errors.push(`console: ${msg.text()}`);
  });
  page.on('pageerror', (error) => errors.push(`pageerror: ${error.message}`));
  await page.goto('http://localhost:3000/', { waitUntil: 'load', timeout: 45000 });
  await page.waitForFunction(() => window.__spidermotion, null, { timeout: 20000 });
  await page.waitForTimeout(1000);
  const info = await fn(page);
  await page.screenshot({ path: `screenshots/${name}.png` });
  const layout = await page.evaluate(() => {
    const ids = ['statusChip', 'camPanel', 'hint', 'btnMask', 'btnFace', 'btnOverlay', 'btnMirror', 'btnReset'];
    const boxes = {};
    for (const id of ids) {
      const el = document.getElementById(id);
      const r = el.getBoundingClientRect();
      boxes[id] = { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height), visible: r.width > 0 && r.height > 0 };
    }
    return {
      viewport: { w: innerWidth, h: innerHeight },
      boxes,
      viewportOverflowX: document.documentElement.scrollWidth > innerWidth,
      viewportOverflowY: document.documentElement.scrollHeight > innerHeight,
    };
  });
  results[name] = { ...info, layout, errors };
  await context.close();
}

await capture('final-start-desktop', { width: 1440, height: 900 }, async (page) => {
  const startHidden = await page.evaluate(() => document.getElementById('startScreen').classList.contains('is-hidden'));
  return { mode: await page.evaluate(() => window.__spidermotion.state.mode), startHidden };
});

await capture('final-demo-desktop', { width: 1440, height: 900 }, async (page) => {
  await page.click('#demoBtn');
  await page.waitForTimeout(3200);
  return page.evaluate(() => window.__spidermotion.snapshot());
});

await capture('final-start-mobile', { width: 390, height: 844 }, async (page) => {
  const startHidden = await page.evaluate(() => document.getElementById('startScreen').classList.contains('is-hidden'));
  return { mode: await page.evaluate(() => window.__spidermotion.state.mode), startHidden };
});

await capture('final-demo-mobile', { width: 390, height: 844 }, async (page) => {
  await page.click('#demoBtn');
