  padding: 8px 10px;
  border-radius: 9px;
  color: #8f98ac;
  transition: background 0.2s ease, color 0.2s ease, transform 0.15s ease;
}

.dock-btn:hover { background: rgba(255, 255, 255, 0.05); color: #d7deeb; }
