  .dock-btn svg { width: 16px; height: 16px; }
  .dock-copy { gap: 1px; }
  .dock-label { font-size: 8px; letter-spacing: 0.07em; }
  .dock-val { font-size: 7px; }
  .dock-btn.icon-only { flex: 0 0 34px; min-width: 34px; padding: 7px; }

  .hint { top: calc(100px + env(safe-area-inset-top, 0px)); bottom: auto; font-size: 9px; padding: 7px 11px; max-width: calc(100vw - 180px); white-space: normal; text-align: center; }

  .start { align-items: flex-end; padding-bottom: calc(36px + var(--safe-b)); }
