  .start h1 { margin-top: 16px; font-size: clamp(44px, 13.5vw, 66px); }
  .start-lede { font-size: 12.5px; line-height: 1.6; margin-top: 16px; }
  .start-feats { margin-top: 20px; width: 100%; }
  .start-feats > div { padding: 10px 0; margin-right: 0; flex: 1; border-right: 1px solid rgba(150, 168, 205, 0.13); }
