  .start-actions { margin-top: 22px; }
  .btn-primary { padding: 13px 18px 13px 22px; font-size: 12px; gap: 18px; flex: 1; justify-content: center; }
  .btn-ghost { padding: 13px 16px; font-size: 10px; }
  .start-privacy { font-size: 9px; margin-top: 16px; }
  .start-legal { font-size: 7px; bottom: calc(10px + var(--safe-b)); }
  .toast { top: calc(96px + env(safe-area-inset-top, 0px)); font-size: 10px; }
