import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const browser = await chromium.launch({ headless: false, args: ['--enable-unsafe-swiftshader'] });
const results = {};

async function shot(name, viewport, action) {
  const context = await browser.newContext({ viewport });
  await context.addInitScript(() => Object.defineProperty(navigator, 'webdriver', { get: () => false }));
  const page = await context.newPage();
  const errors = [];
  page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('pageerror', (e) => errors.push(e.message));
  await page.goto('http://localhost:3000/', { waitUntil: 'load', timeout: 45000 });
  await page.waitForFunction(() => window.__spidermotion);
  await page.waitForTimeout(900);
  if (action) await action(page);
  await page.waitForTimeout(1200);
  await page.screenshot({ path: `screenshots/${name}.png` });
  const info = await page.evaluate(() => {
    const q = (id) => {
      const el = document.getElementById(id);
      const r = el.getBoundingClientRect();
      const s = getComputedStyle(el);
      return { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height), display: s.display, visible: r.width > 0 && r.height > 0 && s.visibility !== 'hidden' };
    };
    const start = document.getElementById('startScreen').getBoundingClientRect();
    const card = document.querySelector('.start-card').getBoundingClientRect();
    return {
      mode: window.__spidermotion.state.mode,
      start: { y: Math.round(start.y), h: Math.round(start.height) },
      card: { y: Math.round(card.y), h: Math.round(card.height), bottom: Math.round(card.bottom) },
      startBtn: q('startBtn'), demoBtn: q('demoBtn'),
      camPanel: q('camPanel'), hint: q('hint'), dock: q('btnMask'),
      overflowX: document.documentElement.scrollWidth > innerWidth,
      overflowY: document.documentElement.scrollHeight > innerHeight,
    };
  });
  results[name] = { ...info, errors };
  await context.close();
}

await shot('mobile-start-390', { width: 390, height: 844 });
await shot('mobile-demo-390', { width: 390, height: 844 }, (p) => p.evaluate(() => window.__spidermotion.demo()));
await shot('mobile-start-375', { width: 375, height: 667 });
await shot('mobile-demo-375', { width: 375, height: 667 }, (p) => p.evaluate(() => window.__spidermotion.demo()));
await shot('tablet-demo-768', { width: 768, height: 1024 }, (p) => p.evaluate(() => window.__spidermotion.demo()));

console.log(JSON.stringify(results, null, 2));
await browser.close();

