import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ headless: false, args: ['--enable-unsafe-swiftshader'] });
const context = await browser.newContext({ viewport: { width: 320, height: 568 } });
await context.addInitScript(() => Object.defineProperty(navigator, 'webdriver', { get: () => false }));
const page = await context.newPage();
await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.waitForFunction(() => window.__spidermotion);
await page.waitForTimeout(1000);
await page.screenshot({ path: 'screenshots/mobile-start-320.png' });
console.log(await page.evaluate(() => {
  const r = (s) => { const x = document.querySelector(s).getBoundingClientRect(); return { y: Math.round(x.y), bottom: Math.round(x.bottom), h: Math.round(x.height) }; };
  return { card: r('.start-card'), eyebrow: r('.start-eyebrow'), h1: r('.start h1'), lede: r('.start-lede'), feats: r('.start-feats'), actions: r('.start-actions'), privacy: r('.start-privacy'), legal: r('.start-legal') };
}));
await browser.close();

