import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ headless: false, args: ['--enable-unsafe-swiftshader'] });
const results = {};

async function shot(name, viewport, demo = false) {
  const context = await browser.newContext({ viewport });
  await context.addInitScript(() => Object.defineProperty(navigator, 'webdriver', { get: () => false }));
  const page = await context.newPage();
  const errors = [];
  page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('pageerror', (e) => errors.push(e.message));
  await page.goto('http://localhost:3000/', { waitUntil: 'load' });
  await page.waitForFunction(() => window.__spidermotion);
  await page.waitForTimeout(800);
  if (demo) {
    await page.click('#demoBtn');
    await page.waitForTimeout(2200);
  }
  await page.screenshot({ path: `screenshots/${name}.png` });
  results[name] = await page.evaluate(() => {
    const box = (id) => { const el = document.getElementById(id); const r = el.getBoundingClientRect(); const s = getComputedStyle(el); return { x: Math.round(r.x), y: Math.round(r.y), right: Math.round(r.right), bottom: Math.round(r.bottom), w: Math.round(r.width), h: Math.round(r.height), display: s.display, visible: r.width > 0 && r.height > 0 && s.visibility !== 'hidden' }; };
    const legal = document.querySelector('.start-legal').getBoundingClientRect();
    const privacy = document.querySelector('.start-privacy').getBoundingClientRect();
    return {
      mode: window.__spidermotion.state.mode,
      startBtn: box('startBtn'),
      demoBtn: box('demoBtn'),
      privacyBottom: Math.round(privacy.bottom),
      legalTop: Math.round(legal.y),
      overlapLegalPrivacy: privacy.bottom > legal.y,
      dock: box('btnMask'),
      camPanel: box('camPanel'),
      hint: box('hint'),
      overflowX: document.documentElement.scrollWidth > innerWidth,
      overflowY: document.documentElement.scrollHeight > innerHeight,
    };
  });
  results[name].errors = errors;
  await context.close();
}

for (const [w, h] of [[390, 844], [375, 667], [320, 568]]) {
