import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const browser = await chromium.launch({
  headless: false,
  args: [
    '--use-fake-ui-for-media-stream',
    '--use-fake-device-for-media-stream',
    '--enable-unsafe-swiftshader',
    '--ignore-gpu-blocklist',
  ],
});
const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
await context.grantPermissions(['camera'], { origin: 'http://localhost:3000' });
await context.addInitScript(() => Object.defineProperty(navigator, 'webdriver', { get: () => false }));
const page = await context.newPage();
const errors = [];
page.on('console', (m) => { if (m.type() === 'error') errors.push(`console: ${m.text()}`); });
page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));
await page.goto('http://localhost:3000/', { waitUntil: 'load', timeout: 45000 });
await page.waitForFunction(() => window.__spidermotion);
await page.waitForTimeout(800);
await page.click('#startBtn');
await page.waitForTimeout(1000);

let state = null;
for (let i = 0; i < 45; i++) {
  state = await page.evaluate(() => ({
    ...window.__spidermotion.snapshot(),
    starting: window.__spidermotion.state.starting,
    tracker: window.__spidermotion.state.tracker
      ? {
          pose: Boolean(window.__spidermotion.state.tracker.pose),
          face: Boolean(window.__spidermotion.state.tracker.face),
          delegate: window.__spidermotion.state.tracker.delegate,
          faceDelegate: window.__spidermotion.state.tracker.faceDelegate,
          faceEnabled: window.__spidermotion.state.tracker.faceEnabled,
          faceEvery: window.__spidermotion.state.tracker.faceEvery,
          running: window.__spidermotion.state.tracker.running,
        }
      : null,
    video: {
      w: document.getElementById('video').videoWidth,
      h: document.getElementById('video').videoHeight,
      ready: document.getElementById('video').readyState,
    },
    status: document.getElementById('statusText').textContent,
    hint: document.getElementById('hintText').textContent,
    latency: document.getElementById('latency').textContent,
    startHidden: document.getElementById('startScreen').classList.contains('is-hidden'),
  }));
  console.log(i, JSON.stringify(state));
  if (state.mode === 'live') break;
  await page.waitForTimeout(1500);
}
await page.waitForTimeout(3000);
await page.screenshot({ path: 'screenshots/final-live-desktop.png' });
const final = await page.evaluate(() => ({
  snapshot: window.__spidermotion.snapshot(),
  latency: document.getElementById('latency').textContent,
  hint: document.getElementById('hintText').textContent,
  faceEvery: window.__spidermotion.state.tracker?.faceEvery,
  camMeta: document.getElementById('camMeta').textContent,
  landmark: document.getElementById('landmarkInfo').textContent,
}));
console.log('FINAL', JSON.stringify(final, null, 2));
console.log('ERRORS', JSON.stringify(errors, null, 2));
await browser.close();

